function vstGetModel_Execute( model )
{

	Application.LogMessage("vstGetModel_Execute called");

	logmessage ("Getting " + model);
	vproject = XSIUtils.Environment("VProject");
	staging = vproject.match ("staging");
		fso = new ActiveXObject("Scripting.FileSystemObject");

	if (!staging)
	{
		mainPath = vproject;
	}
	else
	{
		mainPath = vproject.replace ("staging", "main");
	}
	contentPath = mainPath.replace ("game", "content");
	mdlPath = (contentPath + "\\" + model);
	//split out .mdl and add .smd
	smdFile = model.replace (".mdl", ".smd");
	smdPath = (contentPath + "\\" + smdFile);

	logmessage ("Model located at : " + mdlPath);
	logmessage ("SMD located at : " + smdPath);

//see if it exists
		exists = fso.FileExists(smdPath);
	if (exists)
		{
			logmessage (smdPath + " exists");
		}
	else
		{
			referenceSMD = smdPath.replace (".smd", "_reference.smd");
			exists = fso.FileExists(referenceSMD);
			if (exists)
				{
				logmessage (referenceSMD + " exists");
				}
			else
				logmessage (referenceSMD + " does not exist");
		}
			
	fso = new ActiveXObject("Scripting.FileSystemObject");

	return true;
}

